<?php defined('BASEPATH') or exit('No direct script access allowed'); init_head(); ?><div id="wrapper"><?php $this->load->view('admin/_nav'); ?><div class="content"><div class="row"><div class="col-md-8"><div class="panel_s"><div class="panel-body"><h4><?= html_escape($vendor->name); ?> Catalog</h4><table class="table dt-table"><thead><tr><th>SKU</th><th>Name</th><th>Core</th><th>Slim</th><th>Luxe</th></tr></thead><tbody><?php foreach($items as $i){?><tr><td><?= html_escape($i->sku); ?></td><td><?= html_escape($i->name); ?></td><td><?= app_format_money($i->price_core,get_base_currency()); ?></td><td><?= app_format_money($i->price_slim,get_base_currency()); ?></td><td><?= app_format_money($i->price_luxe,get_base_currency()); ?></td></tr><?php }?></tbody></table></div></div></div><div class="col-md-4"><div class="panel_s"><div class="panel-body"><h4>Add / Update Item</h4><?= form_open(admin_url('cabinet_maker/vendor/'.$vendor->id)); ?><?= render_input('sku','SKU','','text',['required'=>true]); ?><?= render_input('name','Name','','text',['required'=>true]); ?><?= render_input('price_core','Core Price',0,'number',['step'=>'.01']); ?><?= render_input('price_slim','Slim Price',0,'number',['step'=>'.01']); ?><?= render_input('price_luxe','Luxe Price',0,'number',['step'=>'.01']); ?><button class="btn btn-primary">Save</button><?= form_close(); ?></div></div></div></div></div></div><?php init_tail(); ?>